// === Tab: mySketch ===
//The 1 year anniversary of Random Velocity Particles,
//	which has 685 views. For the anniversary I'll just add a little thing and see if it works
//Made by 16384 - Feb. 2021

let num = 500;
let pos = [];
let rvel = [];
let rot = [];
let vel = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	for (let i = 0; i < num; i++) {
		pos[i] = createVector(width / 2, height / 2);
		vel[i] = createVector(0, 0);
		rvel[i] = random(-0.2, 0.2);
		rot[i] = random(TWO_PI);
	}
	colorMode(HSB);
}

function draw() {
	for (let i = 0; i < pos.length; i++) {
		pos[i].add(vel[i]);

		let rotationAdd = random(-0.05, 0.05);
		rvel[i] += rotationAdd;
		rot[i] += rvel[i];
		vel[i].x += cos(rot[i]) * 0.03;
		vel[i].y += sin(rot[i]) * 0.03;

		if (pos[i].x < 0 || pos[i].x > width || pos[i].y < 0 || pos[i].y > height) {
			vel[i].mult(0);
		}
		//Next line sets the stroke color, smoothly randomized in respect to the current time, just to add some diversity 
		stroke((frameCount / 2 + map(noise(minute()) + noise(second()/100) * 0.1, 0, 1.1, 0, 255)) % 255, 255, 255);
		line(pos[i].x, pos[i].y, pos[i].x + vel[i].x * 2, pos[i].y + vel[i].y * 2);
	}
}

function keyPressed() {
	if (key == 'r') {
		pos = [];
		vel = [];
		for (let i = 0; i < num; i++) {
			pos[i] = createVector(width / 2, height / 2);
			vel[i] = createVector(0, 0);
		}
		background(0);
	}
}

